draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // draw a stick figure
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.arc(W/2, H/2, 20, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 20);
  ctx.lineTo(W/2, H/2 + 50);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 50);
  ctx.lineTo(W/2 - 20, H/2 + 80);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 50);
  ctx.lineTo(W/2 + 20, H/2 + 80);
  ctx.stroke();

  // draw a food plate
  ctx.beginPath();
  ctx.arc(W/2 + 50, H/2 + 100, 30, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.fillStyle = 'green';
  ctx.beginPath();
  ctx.arc(W/2 + 50, H/2 + 100, 20, 0, 2 * Math.PI);
  ctx.fill();

  // animate the food plate
  ctx.save();
  ctx.translate(W/2 + 50, H/2 + 100);
  ctx.rotate(Math.sin(t));
  ctx.beginPath();
  ctx.moveTo(0, 0);
  ctx.lineTo(20, 10);
  ctx.stroke();
  ctx.restore();

  ctx.restore();
}
